291	func TestHealthFailures(t *testing.T) {
292		input := `{"requests":[
293			{"service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h:1"}]},
294			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":5,"healthy":true},
295			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":3,"healthy":true},
296			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":5,"healthy":false,"reason":"different"},
297			{"type":"health","service":"svc","instanceId":"ghost","expectedRevision":1,"sequence":1,"healthy":true},
298			{"type":"health","service":"svc","instanceId":"a","expectedRevision":2,"sequence":6,"healthy":true},
299			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":6,"healthy":true}
300		]}`
301		out, code := runRegisterWith(t, input)
302		if code != 1 {
303			t.Fatalf("exit code: %d", code)
304		}
305		var got registerOutput
306		if err := json.Unmarshal([]byte(out), &got); err != nil {
307			t.Fatalf("output is not JSON: %v", err)
308		}
309		if len(got.Results) != 7 {
310			t.Fatalf("results: %+v", got.Results)
311		}
312		// 0: create
313		if r := got.Results[0]; !r.OK || r.Revision != 1 {
314			t.Fatalf("result 0: %+v", r)
315		}
316		// 1: healthy seq 5
317		if r := got.Results[1]; !r.OK || !r.Changed || r.Sequence != 5 {
318			t.Fatalf("result 1: %+v", r)
319		}
320		// 2: stale (3 < 5)
321		if r := got.Results[2]; r.OK || r.Error != "stale" || r.Sequence != 5 {
322			t.Fatalf("result 2: %+v", r)
323		}
324		// 3: same seq 5, different content -> conflict
325		if r := got.Results[3]; r.OK || r.Error != "conflict" || r.Sequence != 5 {
326			t.Fatalf("result 3: %+v", r)
327		}
328		// 4: instance missing -> not_found
329		if r := got.Results[4]; r.OK || r.Error != "not_found" || r.Revision != 1 {
330			t.Fatalf("result 4: %+v", r)
331		}
332		// 5: wrong revision -> conflict
333		if r := got.Results[5]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 2 || r.ActualRevision != 1 {
334			t.Fatalf("result 5: %+v", r)
335		}
336		// 6: healthy seq 6 succeeds (state still healthy from result 1)
337		if r := got.Results[6]; !r.OK || !r.Changed || r.Sequence != 6 {
338			t.Fatalf("result 6: %+v", r)
339		}
340	}
