739			t.Fatalf("b recovery: %+v", r)
740		}
741		// The failed selects and health report never moved the cursor off a, so
742		// the rotation continues at b rather than restarting at the smallest id.
743		if r := got.Results[10]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 22 || r.Revision != 2 {
744			t.Fatalf("rotation should resume after a at b: %+v", r)
745		}
746		// The new address rejoins selection carrying its new address and the new
747		// observation's sequence.
748		if r := got.Results[11]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 2 {
749			t.Fatalf("new address should be selected with its new observation: %+v", r)
750		}
751		// The final list reflects only the committed changes.
752		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
753			t.Fatalf("services: %+v", got.Services)
754		}
755		insts := got.Services[0].Instances
756		if len(insts) != 2 {
757			t.Fatalf("instances: %+v", insts)
758		}
759		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "healthy" || insts[0].Sequence != 1 || insts[0].Reason != "" {
