767	func TestRejectedHealthKeepsHealthyInstanceEligible(t *testing.T) {
768		// A healthy instance that receives a stale or same-sequence conflicting
769		// "unhealthy" report keeps its accepted observation: the rejections state
770		// the reason and the accepted sequence, and the instance stays in the
