124		if r := got.Results[8]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
125			t.Fatalf("result 8 session survives resubmission: %+v", r)
126		}
127		// 9: the reuse did not move the cursor off i2; unhealthy i3 and unknown i4
128		// are not candidates, so the plain rotation wraps past the end to i1.
129		if r := got.Results[9]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
130			t.Fatalf("result 9 plain select wraps to i1 regardless of resubmission order: %+v", r)
131		}
132	
133		// 10: identical content does not bypass the revision gate. The list is
134		// valid (reordered again) but expectedRevision 2 mismatches the current 1:
135		// conflict, with the reason and both revisions, and no false success.
136		if r := got.Results[10]; r.OK || r.Error != "conflict" ||
137			r.Reason != `service "svc" is at revision 1, not 2` ||
138			r.Revision != 1 || r.ExpectedRevision != 2 || r.ActualRevision != 1 {
139			t.Fatalf("result 10 identical content with wrong revision must conflict: %+v", r)
140		}
141	
142		// 11: the conflict cleared neither the session binding nor the cursor.
143		if r := got.Results[11]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
144			t.Fatalf("result 11 session must survive the conflict: %+v", r)
145		}
146		// 12: a plain select continues just after the last real rotation (i1 from
147		// result 9) to i2 instead of restarting at the smallest id.
148		if r := got.Results[12]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:2" || r.Sequence != 22 || r.Revision != 1 {
149			t.Fatalf("result 12 plain select continues after i1: %+v", r)
150		}
151	
152		// 13: a later duplicate at the correct revision still succeeds unchanged.
153		if r := got.Results[13]; !r.OK || r.Changed || r.Revision != 1 {
154			t.Fatalf("result 13 correct-revision duplicate must be unchanged: %+v", r)
155		}
156		// 14: later items in the batch keep working against only the accepted
157		// state: a newer observation for i1 is accepted without a revision bump.
158		if r := got.Results[14]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 12 {
159			t.Fatalf("result 14 later observation: %+v", r)
160		}
161		// 15: the existing session reflects i1's latest accepted sequence through
162		// its binding — the conflict and resubmissions never replaced it.
163		if r := got.Results[15]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 12 || r.Revision != 1 {
164			t.Fatalf("result 15 session reflects the latest sequence: %+v", r)
165		}
166	
167		// The final list keeps the existing sorting (by service then by id) and
168		// field meanings: revision stays 1; i1 healthy at the new sequence; i2
169		// untouched; i3 unhealthy with its trimmed reason; i4 still unknown/0.
170		if len(got.Services) != 1 {
171			t.Fatalf("services: %+v", got.Services)
172		}
173		svc := got.Services[0]
174		if svc.Service != "svc" || svc.Revision != 1 {
175			t.Fatalf("service view: %+v", svc)
176		}
177		wantInsts := []registerInstance{
178			{ID: "i1", Address: "h1:1", Health: "healthy", Sequence: 12},
179			{ID: "i2", Address: "h2:2", Health: "healthy", Sequence: 22},
180			{ID: "i3", Address: "h3:3", Health: "unhealthy", Sequence: 33, Reason: "磁盘故障"},
