	// latest accepted sequence 1 — not svc-a's 20.
	if r := got.Results[5]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 1 || r.Revision != 1 {
		t.Fatalf("result 5 svc-b selects its own i1: %+v", r)
	}

