	// sequence-5 report did not heal svc-a's i1.
	if r := got.Results[8]; r.OK || r.Error != "no_healthy" ||
		r.Revision != 1 || r.InstanceID != "" || r.Address != "" {
		t.Fatalf("result 8 svc-a still no_healthy after rejections: %+v", r)
	}

